// Room codes and nickname hygiene.
// Codes avoid the characters people confuse (0/O, 1/I): 32 symbols ^ 6 = about 1.07 billion codes, generated by the server and unique among all rooms.

const ALPHA = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';                                      // no I, O, 0, 1
export const ROOM_CODE_LENGTH = 6;

export function newRoomCode(rng) { return Array.from({ length: ROOM_CODE_LENGTH }, () => ALPHA[Math.floor(rng() * ALPHA.length)]).join(''); }

// "k7q-4p2" -> "K7Q4P2"; anything that cannot be a code -> null (the caller answers "room not found" without revealing why).
export function normalizeRoomCode(input) {
  if (typeof input !== 'string') return null;
  const c = input.toUpperCase().replace(/[\s\-_]/g, '');
  return new RegExp(`^[${ALPHA}]{${ROOM_CODE_LENGTH}}$`).test(c) ? c : null;
}

// Nickname is display data only. It is never an identity and never used for authorization.
export function cleanNickname(input) {
  const s = String(input ?? '').replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2066-\u2069\ufeff]/g, '').replace(/\s+/g, ' ').trim();
  const cut = [...s].slice(0, 16).join('').trim();
  return cut || 'لاعب';
}
